        break;
    case '。':
         result = baseUrl+'{{page==1?"v2/all.json":"all/post.json"}}?key=' + key.slice(1)  + '&sortType=0&version=1&offset=' + offset + '&limit=20';
         break
    case '%':
        result = baseUrl+'grain.json?key='+key.slice(1)+'&limit=10&offset=' + offset;
        break;
    default:
        let header = {
            "headers": {
                "Content-Type": "application/x-www-form-urlencoded;charset=utf-8",
                "deviceid": java.androidId(),
                "if-modified-since": String(new Date()).replace(/(.*?)\s(.*?)\s(.*?)\s(.*?)GMT.*/,'$1, $3 $2 $4 GMT')
            }
        };

        result = baseUrl+'post.json?key=' + key + '&sortType=0&version=1&offset=' + offset + '&limit=20,' + JSON.stringify(header);
}

