}

function jsonToLrc(jsonText) {
    const {java} = this;

  var data = typeof jsonText === 'string' ? JSON.parse(jsonText) : jsonText;

  function pad(n, w) {
    if (w === undefined) w = 2;
    return String(Math.floor(n)).padStart(w, '0');
  }

  function toTimeTag(ms) {
    var totalSeconds = ms / 1000;
    var minutes = Math.floor(totalSeconds / 60);
    var seconds = totalSeconds % 60;
    return (
      pad(minutes) +
      ':' +
      pad(seconds, 2) +
      '.' +
      pad((seconds % 1) * 100, 2)
    );
  }

  var lines = [];
  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    var timeTag = toTimeTag(item.time_begin);
    var text = item.text != null ? item.text : '';
    lines.push('[' + timeTag + ']' + text);
  }

  return lines.join('\n');
}


function getSvgCode() {
	  const {cache,source} = this;
	  let code =  cache.getFile(source.getKey()+"_guaner_svg") || cache.getFile("guaner_svg") || `<svg viewBox="0 0 1000 800" xmlns="http://www.w3.org/2000/svg">
    <path d="M865 100 h-600c-60 0-110 50-110 110v150l-120 80 120 80v150c0 60 50 110 110 110h600c60 0 110-50 110-110V210c0-60-50-110-110-110z  " fill="none" stroke="边" stroke-width="40"/>
    <text x="570" y="565" font-family="Roboto Condensed" text-anchor="middle" dominant-baseline="middle" font-size="420" font-weight="bold" fill="字">
      数量
    </text>
  </svg>`;
	  return String(code)
}

function getChapterSvgCode(){
    const {cache,source} = this;
    let code =  cache.getFile(source.getKey()+"_guaner_svg_chapter") 
        || cache.getFile("guaner_svg_chapter") || "";
        return String(code);
}




function getSvg(totalnum) {
    let {
        java,cache
    } = this;

    try{
    let co = "#" + String(java.getReadBookConfigMap()["textColor"]).match(/.{6}$/)[0];
    if (String(java.getThemeConfigMap()["isNightTheme"]) === "true") {
        co = "#" + String(java.getReadBookConfigMap()["textColorNight"]).match(/.{6}$/)[0];
    }
    let color = [co, co];
    totalnum = totalnum > 999 ? "999" : totalnum;
    let dpstyle = this.getSvgCode();

    if(totalnum === 0){
        dpstyle = this.getChapterSvgCode();
    }

    let svg = dpstyle.replace(/"边"/g,`"${color[0]}"`)
    .replace(/"字"/g,`"${color[1]}"`)
    .replace(/数量/g,totalnum);
    return "data:image/svg+xml;base64," + java.base64Encode(svg);
    }catch(e){
        java.log(e)
    }
}


function getImage(comment_total,postid, blogid,pid,type) {
    const {chapter,java} = this;
    if(type && this.getChapterSvgCode()){
       return `<img src="data:image/svg+xml;base64,${this.java.base64Encode(this.getChapterSvgCode().substring(110,120))},{"click":"toReview(0,${postid}, ${blogid}, '${chapter?String(chapter.title).replace(/\s+/g,''):''}',1)","type":"jjwx","style":"FULL","js":"getSvg(0)"}">`;
}

   return `<img src="data:image/svg+xml;base64,${this.java.base64Encode(this.getSvgCode().substring(110,120))},{"style":"TEXT","type":"lofter","js":"getSvg(${comment_total})","click":"toReview(${comment_total},${postid}, ${blogid}, '${pid}')"}">`;
}



function toReview(comment_total,postid, blogid, pid,t) {
    const {
        java,source
