0px;height:60px;display:flex;align-items:center;justify-content:center;flex-direction:column;font-size:20px;z-index:100;}#top,#down{opacity:0.4}#top:hover,#down:hover{opacity:1}.ef{width:24px;display:inline-block;vertical-align:middle;margin-top:-4px;}.comment-item:first-of-type{margin-top:20px}
